/// <summary>
/// Charge through invoice posting class
/// </summary>
public class METCBCTInvoicePosting
{
}

Method.Source:
/// <summary>
///  Create a new instance of  METCBCTInvoicePosting class
/// </summary>
/// <returns>
/// A new instance of METCBCTInvoicePosting class
/// </returns>
public static METCBCTInvoicePosting construct()
{
    return new METCBCTInvoicePosting();
}

    /// <summary>
    /// Entry point of the class
    /// </summary>
    /// <param name="args"><c>Args</c></param>
    static void main(Args args)
    {
        FormDataSource               formDataSource;
        METCBCTInvoiceHeaderTable    invoiceHeaderTable;
    
        if (args && args.dataset() == tableNum(METCBCTInvoiceHeaderTable))
        {
            invoiceHeaderTable = args.record();
            if (invoiceHeaderTable.Status == METCBCTInvoiceStatus::Processed)
            {
                throw Error("@MET:ChargethroughInvoiceIsAlreadyProcessed");
            }
            
            // reusing controller class from periodic
            METCBCTInvoicePostingController invoicePostingController = METCBCTInvoicePostingController::construct();
            invoicePostingController.parmMethodName(methodStr(METCBCTInvoicePostingService, processFromUI));
            METCBCTInvoicePostingContractUI contract = invoicePostingController.getDataContractObject();

            SysRecordSortedList cbCtInvoiceHeaderTableList = new SysRecordSortedList(tableNum(METCBCTInvoiceHeaderTable));
            cbCtInvoiceHeaderTableList.sortOrder(fieldNum(METCBCTInvoiceHeaderTable, Number), fieldNum(METCBCTInvoiceHeaderTable, RecId));
            cbCtInvoiceHeaderTableList.ins(invoiceHeaderTable);
            contract.parmInvoiceList(cbCtInvoiceHeaderTableList.pack());

            invoicePostingController.parmDialogCaption("@MET:CBCTProcessChargeThroughInvoice");
            invoicePostingController.parmExecutionMode(SysOperationExecutionMode::Synchronous);
            invoicePostingController.parmShowDialog(false);
            invoicePostingController.parmLoadFromSysLastValue(false);
            invoicePostingController.startOperation();

        }
        else
        {
            throw error(strfmt("@SYS19306","@MET:Posting"));
        }
    
        if (FormDataUtil::isFormDataSource(args.record()))
        {
            formDataSource = FormDataUtil::getFormDataSource(args.record());
            formDataSource.research(true);
        }
    }
